// frontend/src/components/Header.jsx

import React, { useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import "./Header.css";

const Header = () => {
  const [usuario, setUsuario] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    // Intentar obtener usuario del localStorage
    const token = localStorage.getItem('token');
    const usuarioStr = localStorage.getItem('usuario');
    if (token && usuarioStr) {
      setUsuario(JSON.parse(usuarioStr));
    } else {
      setUsuario(null);
    }
  }, []);

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('usuario');
    setUsuario(null);
    navigate('/login');
  };

  return (
    <header className="header-artisa">
      <div className="header-logo">
        {/* Cambia la ruta si tu logo está en otra carpeta */}
        <img src="/img/logo.png" alt="Artisa logo" className="logo-img" />
      </div>
      <nav className="header-nav">
        <Link to="/">Inicio</Link>
        <Link to="/catalogo">Catalogo</Link>
        <Link to="/blog">Blog</Link>
        {usuario ? (
          <div className="header-user-menu">
            <img
              src={usuario.foto || '/img/user-default.png'}
              alt="Perfil"
              className="header-user-avatar"
              style={{ width: 32, height: 32, borderRadius: '50%', objectFit: 'cover', marginRight: 0 }}
            />
          </div>
        ) : (
          <Link to="/login">Iniciar sesión</Link>
        )}
      </nav>
    </header>
  );
};

export default Header;
